refentry.refsect1:
&reftitle.description;

 public boolYaf_Request_Abstract::isHead



 Comprueba si la petición se ha enviado con el método HEAD.

  &reftitle.examples;

   Ejemplo de Yaf_Request_Abstract::isHead


<?php
class FeedController extends Yaf_Controller_Abstract
{
    public function indexAction()
    {
        // Suponiendo que la petición se ha enviado con HEAD /feed
        if ($this->getRequest()->isHead()) {
            // solo cabeceras, se omite el renderizado del cuerpo
            return false;
        }
    }
}
?>
